function v3_report_notes(g,T,out)
f=fopen(fullfile(out,'reports',[g '.md']),'a','n','UTF-8');c=onCleanup(@()fclose(f));fprintf(f,'## 分析与边界\n\n');
switch g
case 'E1'
for cmg=[false true],M=T(T.cmg==cmg,:);fprintf(f,'CMG=%d：当前 %d/72 条记录；通过%d、跟踪失败%d、控制器异常%d、模型域外%d、基础设施失败%d。域外不是物理不可达，缺失记录不作为失败。\n\n',cmg,height(M),sum(strcmp(M.status,'SUCCESS')),sum(strcmp(M.status,'TRACKING_FAIL')),sum(strcmp(M.status,'CONTROLLER_FAIL')),sum(strcmp(M.status,'MODEL_DOMAIN_FAIL')),sum(strcmp(M.status,'INFRA_FAIL')));end
fprintf(f,'最短时间仅指已测试离散参考过渡时长；2s通过只能说明最短已测试为2s，不能断言理论下限。完整配对、可比较子集与失败明细见 E1_paired.csv。气动表迎角边界是当前替代模型的工程有效域保护，不是经验证的真实失速/飞行安全阈值。\n\n![可行域](../figures/E1_feasibility.png)\n\n![最短已测试时长](../figures/E1_min_duration.png)\n');
case 'E2'
cfg=jsondecode(fileread(fullfile(out,'calibration','pid_frozen.json')));fprintf(f,'冻结增益 Kp=[%g,%g,%g]，Ki=[%g,%g,%g]，Kd=[%g,%g,%g]。13个有限候选、4个独立任务，共52次标定；所有候选分数和失败见 calibration/tuning_scores.json。该整定不是全局最优PID保证。两种PID仅卸载开关不同；比较传统控制栈与联合MPC栈，不能把全部差异归为单独PID算法。\n\n',cfg.kp,cfg.ki,cfg.kd);
for task=1:2,S=T(strcmp(T.pair_id,sprintf('V2_M%d',task)),:);off=S(strcmp(S.method,'PID_surface_first'),:);on=S(strcmp(S.method,'PID_surface_first_unload'),:);if ~isempty(off)&&~isempty(on),fprintf(f,'构型%d：卸载关/开，末端H范数 %.4f/%.4f Nms；后续机动段RMSE %.4f/%.4f°；实际总控制力矩残差 RMS %.4f/%.4f Nm。必须在完整域内条件下解释收益或退化，H下降不等于方向控制权限恢复。\n\n',task,off.H_final_Nms,on.H_final_Nms,off.maneuver_rmse_deg,on.maneuver_rmse_deg,off.actual_allocation_residual_rms_Nm,on.actual_allocation_residual_rms_Nm);end;end
fprintf(f,'“实际总控制力矩”=实测气动力矩+CMG反作用力矩，不包含外扰及单列的omega×H耦合。真实舵机补偿存在滞后；不以命令增量相消声称实际瞬时相消。分事件指标见 E2_event_metrics.csv；C1末次机动52s结束，60s内仅观察到8s后段，不能声称覆盖完整10s后段。图中的分轴权限是冻结gamma的一拍方向支撑，非其他轴为零时的独立力矩能力。每个初始gamma/H/A/sigma均见各case/detail_metrics.json。\n\n![单次对照](../figures/E2_single.png)\n\n![卸载与后续任务](../figures/E2_unload_1.png)\n\n![完整卸载机理1](../figures/E2_mechanism_1.png)\n\n![完整卸载机理2](../figures/E2_mechanism_2.png)\n\n![连续任务1](../figures/E2_continuous_1.png)\n\n![连续任务2](../figures/E2_continuous_2.png)\n');
case 'E3'
L=T(strcmp(T.id,'V3_L'),:);S=T(strcmp(T.id,'V3_S'),:);Z=T(strcmp(T.id,'V3_Z'),:);if isempty(L)||isempty(S)||isempty(Z),return;end
fprintf(f,'L/S机动段35–40s RMSE %.4f/%.4f°；机动后40–50s RMSE %.4f/%.4f°。Z是保持任务，不参加机动排名。\n\n34.8s正俯仰一拍可达投影上界 L/S/Z=%.3f/%.3f/%.3f Nm；最小奇异值 %.3f/%.3f/%.3f。这是冻结当前gamma、带真实当前框架速率和0.2s加速度盒约束的局部方向支撑，不是其他轴力矩为零的纯俯仰权限。\n\n',L.maneuver_rmse_deg,S.maneuver_rmse_deg,L.post_rmse_deg,S.post_rmse_deg,L.pitch_positive_support_at_onset_Nm,S.pitch_positive_support_at_onset_Nm,Z.pitch_positive_support_at_onset_Nm,L.sigma_min_at_onset,S.sigma_min_at_onset,Z.sigma_min_at_onset);
if all([L.migrate_10deg_s S.migrate_10deg_s Z.migrate_10deg_s]<1),fprintf(f,'重要：三组10°绝对框架迁移阈值都在共同启动段1s内跨越。该绝对阈值提前量不能作为未来任务预置的独立证据；应看L−Z的任务相关构型差与11.8s之后的演化，不能将共同启动漂移宣称为预测性迁移。\n\n');end
fprintf(f,'准备段有效力矩阈值固定1 Nm，L反号比例%.2f%%，有效样本%d；反号只支持力矩配合现象，不能证明姿态没有代价。预测网格也不同，L/S不能单独识别迁移对跟踪的独立因果贡献。历史onset8s时域扫描另表，不混算新onset35s结果。\n\n![真实构型迁移](../figures/E3_migration.png)\n',L.opposite_torque_pct,L.opposite_effective_samples);
case 'E4'
fprintf(f,'非整数终点按实际1ms网格记录，理论周期终点缺口小于1ms，不补造采样。主指标为末两个周期窗口的基频增益、正向相位滞后（参考相位减实际相位）及直接俯仰RMSE；VALID_POOR_TRACKING保留全部连续指标，不剔除不利频点。工程可接受区域固定为gain≥−3dB、绝对相位≤45°且俯仰RMSE≤0.5A，仅是辅助判据。\n\n');
S=T(T.amplitude_deg==1 & (abs(T.frequency_Hz-.1)<1e-9 | abs(T.frequency_Hz-.15)<1e-9),:);fprintf(f,'### 0.10/0.15Hz 专项审计\n\n|频率|方法|CMG|gain dB|lag °|pitch RMSE °|bias °|fit residual °|qbar范围 Pa|\n|---:|---|---:|---:|---:|---:|---:|---:|---|\n');for k=1:height(S),fprintf(f,'|%.2f|%s|%d|%.3f|%.3f|%.3f|%.3f|%.3f|%.3g–%.3g|\n',S.frequency_Hz(k),string(S.method(k)),S.cmg(k),S.gain_db(k),S.phase_lag_deg(k),S.pitch_rmse_deg(k),S.bias_deg(k),S.fit_residual_deg(k),S.qbar_min_Pa(k),S.qbar_max_Pa(k));end
fprintf(f,'\n在1°专项审计中，0.10/0.15Hz：仅舵面MPC均为低响应，PID均未满足固定工程判据，联合MPC均满足。因此旧的“0.10不通过、0.15通过”没有在本次1°三方法对照中重现；其他幅值/频点的非单调行为仍完整保留。\n\n不同频率的飞行时间窗不同，机体高度/动压/迎角在变化，MPC含参考预瞄，不能把跨频率曲线称严格LTI频响或直接报告带宽倍数。异常原因须结合基频、相位、偏置、趋势、谐波和真实执行器/飞行状态解释；本报告不以平滑/删除点消除非单调现象。两份 anomaly_fit_metrics.csv 还记录末两周期内实际SQP尝试、QP求解、接受步均值与有拒绝步的周期比例。低响应gain ratio<0.05的相位只作带旗标记录，图中用叉标示，不能作可靠相位比较。灰色RMSE格子表示没有有效末段指标，不视作零误差。\n\n非单调现象的唯一主因尚未通过固定飞行工况、固定网格等单变量反事实试验隔离；工况变化、参考预瞄、非均匀时域及有限SQP步都是需要区分的因素，不能仅凭这组多频率数据认定其中某项是唯一原因。\n\n![增益](../figures/E4_gain_db.png)\n\n![相位滞后](../figures/E4_phase_lag_deg.png)\n\n![误差](../figures/E4_RMSE.png)\n\n![0.10Hz审计](../figures/E4_anomaly_100.png)\n\n![0.15Hz审计](../figures/E4_anomaly_150.png)\n');
end
end
